export type ParsedTransferSubscriptionInstruction<
  TProgram extends string = typeof SUBSCRIPTIONS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The subscription delegation PDA */
    subscriptionPda: TAccountMetas[0];
    /** The plan PDA */
    planPda: TAccountMetas[1];
    /** The subscription-authority PDA */
    subscriptionAuthority: TAccountMetas[2];
    /** The delegator's ATA to transfer from */
    delegatorAta: TAccountMetas[3];
    /** The receiver's ATA to transfer to */
    receiverAta: TAccountMetas[4];
    /** The authorized puller (plan owner or whitelisted) */
    caller: TAccountMetas[5];
    /** The token mint */
    tokenMint: TAccountMetas[6];
    /** Token program */
    tokenProgram: TAccountMetas[7];
    /** The event authority PDA */
    eventAuthority: TAccountMetas[8];
    /** This program (for self-CPI) */
    selfProgram: TAccountMetas[9];
  };
  data: TransferSubscriptionInstructionData;
};

export function parseTransferSubscriptionInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedTransferSubscriptionInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      subscriptionPda: getNextAccount(),
      planPda: getNextAccount(),
      subscriptionAuthority: getNextAccount(),
      delegatorAta: getNextAccount(),
      receiverAta: getNextAccount(),
      caller: getNextAccount(),
      tokenMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      selfProgram: getNextAccount(),
    },
    data: getTransferSubscriptionInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
